SELECT id, user_id, forecast_date, slot_hour, weather_code, vote_weight, created_at, updated_at
FROM weather_votes
WHERE user_id = #{userId}
  AND forecast_date BETWEEN #{fromDate} AND #{toDate}

SELECT id, user_id, forecast_date, slot_hour, weather_code, vote_weight, created_at, updated_at
FROM weather_votes
WHERE user_id = #{userId}
  AND forecast_date = #{forecastDate}
  AND slot_hour = #{slotHour}
